 public static void main(String[] args)throws Exception {net.minecraft.init.Bootstrap.register();JsonArray rows=new JsonArray();for(boolean chip:new boolean[]{false,true}){BlockTokenSlot block=new BlockTokenSlot(chip?"data_chip_slot":"access_card_slot",chip);NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);BlockPos pos=new BlockPos(0,80,0);world.setBlockState(pos,block.getDefaultState(),2);float hardness=block.getBlockHardness(block.getDefaultState(),world,pos),resistance=block.getExplosionResistance((net.minecraft.entity.Entity)null);if(hardness!=5F||resistance!=6F||block.getHarvestLevel(block.getDefaultState())!=1||!"pickaxe".equals(block.getHarvestTool(block.getDefaultState()))||block.getLightValue(block.getDefaultState(),world,pos)!=0||block.getSoundType(block.getDefaultState(),world,pos,null)!=net.minecraft.block.SoundType.METAL||block.getDefaultState().getMaterial().isToolNotRequired())throw new AssertionError("Released reader properties changed");JsonObject row=new JsonObject();row.addProperty("chip",chip);row.addProperty("hardness",hardness);row.addProperty("explosionResistance",resistance);row.addProperty("harvestTool",block.getHarvestTool(block.getDefaultState()));row.addProperty("harvestLevel",block.getHarvestLevel(block.getDefaultState()));row.addProperty("light",block.getLightValue(block.getDefaultState(),world,pos));row.addProperty("metalSound",block.getSoundType(block.getDefaultState(),world,pos,null)==net.minecraft.block.SoundType.METAL);row.addProperty("toolRequired",!block.getDefaultState().getMaterial().isToolNotRequired());rows.add(row);}JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",rows);Path output=Paths.get(System.getProperty("vandorlabs.standaloneReaderPropertiesReference","build/test-artifacts/standalone-reader-properties-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual standalone reader properties PASS "+rows);}
